      // entitlement'i kosulsuz ekliyor ve bu onu geri siliyor. Once
      // calissaydi silinen anahtar yeniden eklenirdi. Gerekce ve geri
      // acma adimlari dosyanin kendi basinda.
      './plugins/apple-signin-entitlement-kaldir',
    ],
  }
}
