/**
 * TURKCE BULUNMA EKI: "Salepçi Dayı'da", "Kafe'de", "Park'ta", "Sahil'de".
 *
 * Mekan galerisindeki altyazi "Ad · Mekan'da" biciminde (kullanicinin
 * verdigi ornek 2026-09-13). Ek iki kurala bagli:
 *   - unlu uyumu: son unlu kalin (a, i, o, u) ise -da, ince ise -de
 *   - unsuz sertlesmesi: ad sert unsuzle bitiyorsa (p, ç, t, k, f, s,
 *     ş, h) d -> t
 * Ozel ad oldugu icin kesme isaretiyle ayriliyor.
 *
 * Bilerek basit: rakamla ya da yabanci harfle biten adlarda (ornegin
 * "Cafe 34") sonuc yaklasik olabilir; yanlis ek okunmaz bir hata
 * degil, ama kural genisletilecekse yeri burasi.
 */
const KALIN = 'aıouAIOU'
const INCE = 'eiöüEİÖÜ'
const SERT = 'pçtkfsşhPÇTKFSŞH'

export function bulunmaEki(ad: string): string {
  const temiz = ad.trim()
  if (!temiz) return ''

  let kalin = false
  for (let i = temiz.length - 1; i >= 0; i--) {
    const h = temiz[i]
    if (KALIN.includes(h)) {
      kalin = true
      break
    }
    if (INCE.includes(h)) break
  }

  const son = temiz[temiz.length - 1]
  const unsuz = SERT.includes(son) ? 't' : 'd'
  return `${unsuz}${kalin ? 'a' : 'e'}`
}

/** "Salepçi Dayı" -> "Salepçi Dayı'da" */
export function bulunmaHali(ad: string): string {
  const temiz = ad.trim()
  if (!temiz) return ''
  return `${temiz}'${bulunmaEki(temiz)}`
}

