import { bulunmaEki, bulunmaHali } from './turkce-ek'

describe('bulunmaEki', () => {
  it('kalin unluyle biten ad -da alir', () => {
    expect(bulunmaHali('Salepçi Dayı')).toBe("Salepçi Dayı'da")
  })

  it('ince unluyle biten ad -de alir', () => {
    expect(bulunmaHali('Kafe')).toBe("Kafe'de")
  })

  it('sert unsuzle biten kalin ad -ta alir', () => {
    expect(bulunmaHali('Park')).toBe("Park'ta")
  })

  it('sert unsuzle biten ince ad -te alir', () => {
    expect(bulunmaHali('Kebapçı Emin Usta Şubesi Kültürpark İçi Tesis')).toBe(
      "Kebapçı Emin Usta Şubesi Kültürpark İçi Tesis'te"
    )
  })

  it('yumusak unsuzle biten ince ad -de alir', () => {
    expect(bulunmaHali('Sahil')).toBe("Sahil'de")
  })

  it('unluyu son kelimede degil sondan geriye dogru arar', () => {
    // Son unlu "u" (kalin) -> -da; onceki kelimelerin unlusu sayilmaz.
    expect(bulunmaEki('Hadim erikli subesi Okul')).toBe('da')
  })

  it('bos ad icin bos doner', () => {
    expect(bulunmaHali('  ')).toBe('')
  })
})

