import re,glob
for p in glob.glob('src/**/*.tsx',recursive=True):
    if p.endswith(('gizlilik.tsx','kosullar.tsx')) or '.test.' in p: continue
    s=open(p,encoding='utf-8').read()
    s2=re.sub(r'/\*.*?\*/','',s,flags=re.S); s2=re.sub(r'(?<!:)//[^\n]*','',s2)
    hits=[]
    for m in re.finditer(r"""(['"`])((?:(?!\1).){2,120})\1""", s2):
        v=m.group(2)
        if re.search(r'[ğüşıöçĞÜŞİÖÇ]', v) and not v.startswith(('/','#','http')): hits.append(v)
    for m in re.finditer(r'>\s*([^<>{}\n]*[ğüşıöçĞÜŞİÖÇ][^<>{}\n]*)\s*<', s2):
        hits.append('JSX:'+m.group(1).strip())
    if hits: print(p, hits[:6])
EOF

